// Determina o ponto de partida da sync
// Para push: busca eventos atualizados nos últimos 30 min
// Para manual: usa sync_from do body ou últimas 24h
const body = $input.item.json.body || $input.item.json;
const source = body.source || 'push'; // 'push' | 'manual'
const orgId = body.organization_id || $env.DEFAULT_ORG_ID;

const now = new Date();
let syncFrom;

if (source === 'manual' && body.sync_from) {
  syncFrom = body.sync_from;
} else if (source === 'manual') {
  // Últimas 24h para sync manual
  syncFrom = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
} else {
  // Push: últimos 30 min para garantir que pegamos o evento
  syncFrom = new Date(now.getTime() - 30 * 60 * 1000).toISOString();
}

return [{ json: { source, orgId, syncFrom, calendarId: $env.GCAL_CALENDAR_ID } }];

// Normaliza eventos do GCal para o formato do Maestr.ia
const items = $input.item.json.items || [];
const orgId = $('Preparar Parâmetros de Sync').item.json.orgId;

if (items.length === 0) return [{ json: { skip: true, count: 0 } }];

return items.map(ev => {
  const gcalId = ev.id;
  const isDeleted = ev.status === 'cancelled';
  const extProps = ev.extendedProperties?.private || {};
  const maestriaId = extProps.maestria_event_id || null;
  const clickupTaskId = extProps.clickup_task_id || null;

  const startAt = ev.start?.dateTime || (ev.start?.date ? ev.start.date + 'T00:00:00' : null);
  const endAt = ev.end?.dateTime || (ev.end?.date ? ev.end.date + 'T23:59:59' : null);

  return { json: {
    gcal_event_id: gcalId,
    maestria_id: maestriaId,
    clickup_task_id: clickupTaskId,
    is_deleted: isDeleted,
    title: ev.summary || '(sem título)',
    description: ev.description || '',
    location: ev.location || '',
    start_at: startAt,
    end_at: endAt,
    updated: ev.updated,
    organization_id: orgId
  }};
});

// Após criar/atualizar no Maestr.ia, sincroniza para ClickUp
// APENAS se o evento for de terceirizado (tag 'terceirizado' ou campo is_freelancer)
const event = $input.item.json;
const clickupTaskId = $('Normalizar Eventos GCal').item.json.clickup_task_id;
const tags = $('Normalizar Eventos GCal').item.json.tags || [];

// Verifica se é evento de terceirizado
const isFreelancer = tags.includes('terceirizado') || event.is_freelancer === true;

if (!isFreelancer) {
  // Evento interno — não sincroniza com ClickUp
  return [{ json: { skip_clickup: true, ...event } }];
}

if (clickupTaskId) {
  return [{ json: { action: 'update', clickup_task_id: clickupTaskId, ...event } }];
} else {
  return [{ json: { action: 'create', ...event } }];
}
